//! RECONSTRUCTED-UNVERIFIED. Actual original schema/API integration; signed stored
//! source rows are fixtures, not end-to-end publication/storage acceptance.
use std::time::Duration;
use serde_json::{Value,json};
use weebdex_platform::{AppState,Config,domains,domains::catalog::CatalogRepository,protocol::bridge,public_api::{PostgresPublicIdResolver,PublicIdResolver,PublicIdTarget,PublicUuid,ResourceKind}};
use manga_node::{auth,db::{DbConfig,Repository}};
fn uuid(s:&str)->PublicUuid{PublicUuid::parse(s).unwrap()}
fn id(s:&str)->[u8;32]{hex::decode(s).unwrap().try_into().unwrap()}
async fn fixture()->(AppState,Repository){
 let dsn=std::env::var("PLATFORM_AUTH_TEST_DATABASE_URL").expect("Use owned disposable PostgreSQL runner");let pg:tokio_postgres::Config=dsn.parse().unwrap();assert_eq!(pg.get_dbname(),Some("weebdex_platform_test"));assert!(!pg.get_hosts().is_empty());for host in pg.get_hosts(){assert!(matches!(host,tokio_postgres::config::Host::Tcp(host) if host=="127.0.0.1"));}assert!(std::env::var("PLATFORM_TEST_RUNTIME_DIR").unwrap().contains("weebdex-platform/test-runtime/"));
 let state=AppState::connect(Config{database_plaintext_local:true,database_connections:4,..Config::default()},dsn.clone()).await.unwrap();let mut repo=Repository::connect(DbConfig{dsn,connections:1,acquisition_timeout:Duration::from_secs(2),cache_weight:1048576,plaintext_local:true}).await.unwrap();repo.pool=state.db.pool().clone();repo.migrate().await.unwrap();repo.verify_schema().await.unwrap();let end=domains::MIGRATIONS.iter().position(|m|m.version==89).unwrap();state.db.migrate(&domains::MIGRATIONS[..end]).await.unwrap();state.protocol.verify_schema().await.unwrap();state.protocol.install_visibility_function().await.unwrap();(state,repo)
}
async fn original_snapshot(state:&AppState)->Value{
 state.db.client().await.unwrap().query_one("SELECT jsonb_build_object(
 'migrations',(SELECT jsonb_agg(jsonb_build_array(version,encode(checksum,'hex'),applied_at) ORDER BY version) FROM public.schema_migrations),
 'events',(SELECT COALESCE(jsonb_agg(to_jsonb(e) ORDER BY encode(id,'hex')),'[]') FROM public.events e),
 'aliases',(SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY kind,id),'[]') FROM public.compatibility_ids a),
 'accounts',(SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY encode(publisher,'hex')),'[]') FROM public.account_permissions a),
 'publishers',(SELECT COALESCE(jsonb_agg(to_jsonb(p) ORDER BY encode(publisher,'hex')),'[]') FROM public.publisher_permissions p),
 'auth_used',(SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY encode(id,'hex')),'[]') FROM public.auth_used a),
 'outbox',(SELECT COALESCE(jsonb_agg(to_jsonb(o) ORDER BY id),'[]') FROM public.backend_outbox o))",&[]).await.unwrap().get(0)
}
async fn seed(state:&AppState,key:u32,title:&str)->(manga_node::auth::Event,Value){
 let event=auth::sign(&format!("{key:064x}"),1002,vec![],json!({"manifest":auth::hash(format!("synthetic stored-source fixture manifest {key}").as_bytes()),"version":1}).to_string()).unwrap();event.verify().unwrap();
 let metadata=json!({"version":1,"titles":{"en":title},"originalLanguage":"en","status":"ongoing","contentRating":"safe","year":2026,"categories":["Protocol fixture"],"credits":[{"role":"author","name":"Actual fixture author"}]});
 let client=state.db.client().await.unwrap();client.execute("INSERT INTO public.events(id,publisher,kind,created_at,raw_event,state) VALUES($1,$2,1002,$3,$4,'hosted')",&[&id(&event.id).as_slice(),&id(&event.pubkey).as_slice(),&(event.created_at as i64),&serde_json::to_value(&event).unwrap()]).await.unwrap();client.execute("INSERT INTO public.catalogue_metadata(event_id,metadata,title_values,metadata_version) VALUES($1,$2,ARRAY[$3],2)",&[&id(&event.id).as_slice(),&metadata,&title]).await.unwrap();(event,metadata)
}
#[tokio::test]
#[ignore="Requires the explicitly isolated PostgreSQL runner"]
async fn all_original_migrations_alias_imports_and_visibility_remain_authoritative(){
 let(state,repo)=fixture().await;let client=state.db.client().await.unwrap();let h=client.query_one("SELECT count(*),max(version) FROM public.schema_migrations",&[]).await.unwrap();assert_eq!(h.get::<_,i64>(0),52);assert_eq!(h.get::<_,i64>(1),52);
 let(event,_)=seed(&state,1,"Original schema fixture").await;let source_id=id(&event.id);let publisher=id(&event.pubkey);assert!(repo.account_permit(publisher).await.is_err());assert!(repo.publisher_permit(publisher).await.is_err());
 assert_eq!(repo.compatibility_backfill().await.unwrap(),1);let generated=uuid(&manga_node::mangadex_compat::uuid("manga",&event.id));let old=uuid("10101010-1010-4010-8010-101010101010");repo.register_compatibility_alias("manga",old.as_str(),&event.id,true).await.unwrap();assert_eq!(repo.compatibility_id("manga",&event.id).await.unwrap(),old.as_str());
 let page=repo.platform_catalogue_page(None,16).await.unwrap();assert_eq!(page.entries.len(),1);assert!(page.entries[0].visible);assert_eq!(serde_json::to_value(&page.entries[0].event).unwrap(),serde_json::to_value(&event).unwrap());let imported=bridge::import_page(&state).await.unwrap();assert_eq!(imported.imported,1);assert_eq!(imported.rejected,0);
 let native:String=client.query_one("SELECT catalog_id FROM platform.protocol_resource_ids WHERE kind='manga' AND source_target=$1",&[&event.id]).await.unwrap().get(0);assert_eq!(native.len(),10);let before=original_snapshot(&state).await;let end=domains::MIGRATIONS.iter().position(|m|m.version==89).unwrap();state.db.migrate(&domains::MIGRATIONS[..=end]).await.unwrap();assert_eq!(original_snapshot(&state).await,before);state.db.verify_schema(&domains::MIGRATIONS[..=end]).await.unwrap();repo.verify_schema().await.unwrap();
 let resolver=PostgresPublicIdResolver::new(state.db.clone());for a in [&old,&generated]{let r=resolver.resolve(ResourceKind::Manga,a).await.unwrap().unwrap();assert_eq!(r.native_id,native);assert_eq!(r.preferred_id,old);}
 let user_alias=uuid(&repo.compatibility_id("user",&event.pubkey).await.unwrap());let principal=resolver.resolve(ResourceKind::User,&user_alias).await.unwrap().unwrap();assert_eq!(principal.target,PublicIdTarget::ProtocolPublisher{pubkey:event.pubkey.clone()});assert_eq!(client.query_one("SELECT count(*) FROM platform.users WHERE id=$1",&[&principal.native_id]).await.unwrap().get::<_,i64>(0),0);assert_eq!(client.query_one("SELECT count(*) FROM platform.protocol_identity_bindings",&[]).await.unwrap().get::<_,i64>(0),0);
 let catalog=CatalogRepository::new(state.db.clone());assert_eq!(catalog.get_manga(&native).await.unwrap()["title"],"Original schema fixture");let aliases_before:Value=client.query_one("SELECT jsonb_agg(to_jsonb(a) ORDER BY kind,public_id) FROM platform.public_resource_ids a",&[]).await.unwrap().get(0);
 for _ in 0..3{resolver.resolve_many(ResourceKind::Manga,&[old.clone(),generated.clone()]).await.unwrap();resolver.preferred_many(ResourceKind::Manga,std::slice::from_ref(&native)).await.unwrap();resolver.describe_many(ResourceKind::User,std::slice::from_ref(&principal.native_id)).await.unwrap();}
 let aliases_after:Value=client.query_one("SELECT jsonb_agg(to_jsonb(a) ORDER BY kind,public_id) FROM platform.public_resource_ids a",&[]).await.unwrap().get(0);assert_eq!(aliases_before,aliases_after);assert_eq!(original_snapshot(&state).await,before);
 let newer=uuid("20202020-2020-4020-8020-202020202020");repo.register_compatibility_alias("manga",newer.as_str(),&event.id,true).await.unwrap();let after_import=original_snapshot(&state).await;
 // Genuine importer must reconcile a newly preferred alias before manual sync.
 assert_eq!(bridge::import_page(&state).await.unwrap().deferred,0);resolver.sync_protocol_aliases(ResourceKind::Manga,&native).await.unwrap();client.query_one("SELECT platform.public_backfill_resource_ids()",&[]).await.unwrap();for a in [&old,&generated,&newer]{let r=resolver.resolve(ResourceKind::Manga,a).await.unwrap().unwrap();assert_eq!(r.native_id,native);assert_eq!(r.preferred_id,old);}assert_eq!(original_snapshot(&state).await,after_import);
 for state_name in ["candidate","withdrawing","removed"]{client.execute("UPDATE public.events SET state=$2 WHERE id=$1",&[&source_id.as_slice(),&state_name]).await.unwrap();assert!(catalog.get_manga(&native).await.is_err());assert!(repo.compatibility_entry("manga",old.as_str()).await.unwrap().is_none());assert!(resolver.resolve(ResourceKind::Manga,&newer).await.unwrap().is_some());}
 client.execute("UPDATE public.events SET state='hosted' WHERE id=$1",&[&source_id.as_slice()]).await.unwrap();assert!(catalog.get_manga(&native).await.is_ok());client.execute("INSERT INTO public.backend_outbox(event_id,action,payload) VALUES($1,'import',$2)",&[&source_id.as_slice(),&serde_json::to_value(&event).unwrap()]).await.unwrap();assert!(catalog.get_manga(&native).await.is_err());assert!(resolver.resolve(ResourceKind::Manga,&newer).await.unwrap().is_some());client.execute("UPDATE public.backend_outbox SET completed_at=clock_timestamp() WHERE event_id=$1",&[&source_id.as_slice()]).await.unwrap();assert!(catalog.get_manga(&native).await.is_ok());assert!(repo.account_permit(publisher).await.is_err());assert!(repo.publisher_permit(publisher).await.is_err());assert_eq!(bridge::import_page(&state).await.unwrap().deferred,0);assert_eq!(resolver.preferred(ResourceKind::Manga,&native).await.unwrap(),Some(old.clone()));let mapped:String=client.query_one("SELECT compatibility_id FROM platform.protocol_resource_ids WHERE kind='manga' AND source_target=$1",&[&event.id]).await.unwrap().get(0);assert_eq!(mapped,old.as_str());
 let(second,_)=seed(&state,2,"Second immutable source").await;assert_eq!(repo.compatibility_backfill().await.unwrap(),1);assert!(repo.register_compatibility_alias("manga",newer.as_str(),&second.id,true).await.is_err());let second_import=bridge::import_page(&state).await.unwrap();assert_eq!(second_import.deferred,0);assert_eq!(second_import.imported,2);let second_native:String=client.query_one("SELECT catalog_id FROM platform.protocol_resource_ids WHERE kind='manga' AND source_target=$1",&[&second.id]).await.unwrap().get(0);assert_ne!(second_native,native);
 let occupied=uuid("30303030-3030-4030-8030-303030303030");resolver.register_alias(ResourceKind::Manga,&second_native,&occupied).await.unwrap();repo.register_compatibility_alias("manga",occupied.as_str(),&event.id,true).await.unwrap();assert_eq!(bridge::import_page(&state).await.unwrap().deferred,1);assert_eq!(resolver.resolve(ResourceKind::Manga,&occupied).await.unwrap().unwrap().native_id,second_native);assert_eq!(resolver.resolve(ResourceKind::Manga,&newer).await.unwrap().unwrap().native_id,native);repo.register_compatibility_alias("manga",newer.as_str(),&event.id,true).await.unwrap();assert_eq!(bridge::import_page(&state).await.unwrap().deferred,0);repo.verify_schema().await.unwrap();let h=client.query_one("SELECT count(*),max(version) FROM public.schema_migrations",&[]).await.unwrap();assert_eq!(h.get::<_,i64>(0),52);assert_eq!(h.get::<_,i64>(1),52);
}
